# --- DYNAMIC FEE CALCULATION CALLBACK ---

@app.callback(
    Output("fee-total-display", "children"),
    Output("fee-breakdown-display", "children"),
    Input("division-select", "value"),
    Input({'type': 'addon-select', 'index': ALL}, 'value')
)
def calculate_total_fee(selected_division, selected_addons):
    total = 0.0
    breakdown_items = []

    for div in EVENT_CONFIG.get("divisions", []):
        if div["label"] == selected_division:
            total += div["price"]
            breakdown_items.append(
                html.Div(className="d-flex justify-content-between mb-1", children=[
                    html.Span(f"Main Event ({selected_division}):", className="text-truncate me-2"),
                    html.Span(f"${div['price']:.2f}", className="fw-bold text-white")
                ])
            )
            break

    addons_config = EVENT_CONFIG.get("addons", [])
    if selected_addons and len(selected_addons) == len(addons_config):
        for addon_group, selected_val in zip(addons_config, selected_addons):
            if not selected_val:
                continue
            for opt in addon_group.get("options", []):
                if opt["label"] == selected_val:
                    if opt.get("price", 0) > 0:
                        total += opt["price"]
                        short_title = addon_group.get("title", "").split("\n")[0]
                        breakdown_items.append(
                            html.Div(className="d-flex justify-content-between mb-1", children=[
                                html.Span(f"{short_title}:", className="text-truncate me-2", style={"maxWidth": "180px"}),
                                html.Span(f"${opt['price']:.2f}", className="fw-bold text-white")
                            ])
                        )
                    break

    return f"${total:.2f}", breakdown_items

# --- FORM & DISCLAIMER VALIDATION CALLBACK ---

disclaimer_cfg = EVENT_CONFIG.get("disclaimer")
disclaimer_id = disclaimer_cfg.get("id", "disclaimer-agreement") if disclaimer_cfg else None

validation_inputs = [
    Input({'type': 'form-field', 'index': ALL}, 'value'),
    Input({'type': 'form-field', 'index': ALL}, 'id'),
    Input("fee-total-display", "children")
]
if disclaimer_id:
    validation_inputs.insert(2, Input(disclaimer_id, 'value'))

@app.callback(
    Output("payment-validation-store", "data"),
    Output("payment-notice-display", "children"),
    *validation_inputs
)
def validate_form_and_payment(*args):
    field_values = args[0]
    field_ids = args[1]

    if disclaimer_id:
        disclaimer_val = args[2]
        fee_str = args[3]
    else:
        disclaimer_val = None
        fee_str = args[2]

    # 1. Extract total numerical amount
    try:
        amount = float(str(fee_str).replace("$", "").strip())
    except (ValueError, AttributeError):
        amount = 0.0

    # 2. Map field inputs to check required fields
    val_map = {fid['index']: val for fid, val in zip(field_ids, field_values)}
    missing_required = False

    for f in EVENT_CONFIG.get("form_fields", []):
        if f.get("required"):
            val = val_map.get(f['id'])
            if val is None or str(val).strip() == "":
                missing_required = True
                break

    # 3. Check disclaimer agreement match
    disclaimer_agreed = True
    if disclaimer_cfg:
        disclaimer_agreed = (disclaimer_val == "I agree to the above statement")

    is_valid = (not missing_required) and disclaimer_agreed

    # 4. Generate dynamic status banner UI
    if is_valid:
        notice = html.Div([
            html.Div("✓ Application Complete", className="badge bg-success mb-2 p-2 w-100 fs-6"),
            html.P("Complete payment below via PayPal or Card to finalize entry.", className="small text-white-50 mb-0")
        ])
    else:
        reasons = []
        if missing_required:
            reasons.append("Fill out all required contestant fields")
        if disclaimer_cfg and not disclaimer_agreed:
            reasons.append("Select 'I agree to the above statement'")

        notice = html.Div(className="p-3 bg-dark bg-opacity-50 border border-warning rounded text-start", children=[
            html.Div("⚠️ Payment Locked", className="fw-bold text-warning small mb-1"),
            html.P("Complete the following to unlock payment:", className="small text-white-50 mb-1"),
            html.Ul(
                [html.Li(r, className="small text-white-50") for r in reasons],
                className="mb-0 ps-3"
            )
        ])

    return {"is_valid": is_valid, "amount": amount}, notice

# --- CLIENTSIDE CALLBACK: CONDITIONALLY MOUNT PAYPAL ---

app.clientside_callback(
    """
    function(validation_data) {
        const container = document.getElementById("paypal-button-container");
        if (!container) return "";
        
        // Clear container whenever validation status changes
        container.innerHTML = "";
        
        if (!validation_data || !validation_data.is_valid) {
            return "Payment Locked (Form Incomplete)";
        }
        
        if (!window.paypal) {
            console.warn("PayPal SDK not loaded.");
            return "PayPal SDK Missing";
        }
        
        const amount = parseFloat(validation_data.amount) || 0;
        if (amount <= 0) return "Invalid Amount";

        paypal.Buttons({
            style: {
                layout: 'vertical',
                color:  'gold',
                shape:  'rect',
                label:  'paypal'
            },
            createOrder: function(data, actions) {
                return actions.order.create({
                    purchase_units: [{
                        amount: {
                            value: amount.toFixed(2)
                        }
                    }]
                });
            },
            onApprove: function(data, actions) {
                return actions.order.capture().then(function(details) {
                    alert('Transaction completed by ' + details.payer.name.given_name + '! Registration confirmed.');
                });
            },
            onError: function(err) {
                console.error('PayPal Error:', err);
            }
        }).render('#paypal-button-container');
        
        return "PayPal Mounted ($" + amount.toFixed(2) + ")";
    }
    """,
    Output("paypal-mount-status", "children"),
    Input("payment-validation-store", "data")
)

